/* ============================================================
   MODULES · INVERTIX, from the INVERTIX A-to-Z guide: one strategy for NQ and MNQ on the 1-minute chart, with separate trade sections:
   the flip (INVERTIX), EARLY, H/L, PO3, the news fade and the FOMC evening trade. Rules only: no results, win rates or statistics.
============================================================ */
(()=>{
const f1=x=>Math.round(x*10)/10,f2=x=>Math.round(x*100)/100;
/* ---------- generators ---------- */
const stopRule=numGen('The stop',r=>{const s=pick(r,[12,18,24,29,34,48,60,75,90,105,130]);const ans=s<30?0:Math.min(s,90);
  return{q:`The extreme of the manipulation leg is ${s} points from your entry. The INVERTIX rule skips a stop under 30 points and tightens a stop over 90 points to 90. How many points is your stop? (Type 0 if the trade is skipped.)`,ans,unit:'pts',tol:.01,why:s<30?`${s} is under 30 points, so the trade is skipped: the answer is 0.`:s>90?`${s} is over 90, so the stop is tightened to 90 points (and the size is worked out for 90).`:`${s} is between 30 and 90 points, so the stop stays at ${s}.`}});
const targetRule=numGen('The target',r=>{const s=pick(r,[30,40,50,60,80]),d=pick(r,[12,20,28,45,60,90]),ans=Math.max(s,d);
  return{q:`The stop is ${s} points. The nearest unfilled 5-minute or 15-minute gap in your direction is ${d} points from your entry. The target is that gap, but never closer than 1 × the stop. How many points away is your target?`,ans,unit:'pts',tol:.01,why:d>=s?`The gap is ${d} points away, at least 1 × the stop, so the target is the gap: ${d} points.`:`The gap is only ${d} points away, closer than 1 × the stop (${s}), so the target is pushed out to ${s} points.`}});
const beStep=numGen('The stop guide',r=>{const s=pick(r,[30,40,50,60,80]),long=r()<.5,e=pick(r,[20100,21400,24250,27800]),trig=e+(long?1:-1)*s*.5;
  return{q:`${long?'Long':'Short'} at ${fm(e,0)} with a ${s}-point stop. The stop guide says to move your stop to your entry once price is half a stop (0.5 × the stop) in profit. At what price do you make that move?`,ans:trig,unit:'',tol:.3,why:`0.5 × ${s} = ${f1(s/2)} points ${long?'above':'below'} your entry: ${fm(trig,1)}. Then your stop goes to ${fm(e,0)}. You move the real order yourself, once.`}});
const contracts=numGen('Contracts',r=>{const risk=pick(r,[375,500,625,750,1000]),st=pick(r,[30,37,42,60,90]),n=Math.max(1,Math.floor(risk/(st*2)));return{q:`Your risk is $${risk} and the INVERTIX stop is ${st} points. How many MNQ ($2 a point), rounded down (minimum 1)?`,ans:n,unit:'',tol:.01,why:`$${risk} ÷ (${st} × $2) = ${f2(risk/(st*2))}, rounded down to ${Math.floor(risk/(st*2))}${Math.floor(risk/(st*2))<1?', so the minimum of 1':''}.`}});
const earlyStop=numGen('The EARLY stop',r=>{const R=pick(r,[160,240,320,400,480]),ans=Math.min(R/4,90);
  return{q:`An EARLY trade uses a stop of a quarter of the typical day\'s range, up to 90 points. The typical day\'s range is ${R} points. How many points is the EARLY stop?`,ans,unit:'pts',tol:.01,why:`${R} ÷ 4 = ${R/4}${R/4>90?', which is over 90, so the stop is capped at 90':''}.`}});
const hlTarget=numGen('H/L target',r=>{const s=pick(r,[20,25,30,40]),long=r()<.5,e=pick(r,[20150,21360,24480,27720]),ans=e+(long?1:-1)*2*s;
  return{q:`An H/L ${long?'long':'short'} enters at ${fm(e,2)} with a ${s}-point stop. The default take profit is 2 × the stop. At what price is the take profit?`,ans,unit:'',tol:.3,why:`2 × ${s} = ${2*s} points ${long?'above':'below'} the entry: ${fm(ans,2)}. The break-even move comes earlier, at 1 × the stop.`}});
const newsRisk=numGen('The news fade',r=>{const c=pick(r,[40,48,55,62,75,90]),what=pick(r,['stop','target']),ans=what==='stop'?c:2*c;
  return{q:`The 1-minute news candle spiked ${c} points. The news fade stop is 1 × that candle\'s range and the take profit is 2 × the stop. How many points is the ${what}?`,ans,unit:'pts',tol:.01,why:what==='stop'?`The stop is 1 × the news candle\'s range: ${c} points.`:`The stop is ${c} points and the take profit is 2 × the stop: ${2*c} points.`}});
const keyLevel=r=>{const k=pick(r,[['Price drops into an unfilled bullish 15-minute gap.','A key level for a long','Not a key level: too small a timeframe','A signal to buy at once','The flip'],['A big wick pokes into a bearish gap on the 1-hour chart and is rejected.','A rejection block: a key level for a short','Not a key level: only gaps count','A signal to buy at once','The flip'],['Price trades into a bullish 5-minute gap and nothing higher.','Not enough: the key level must be 15m or higher, a rejection block or an IML','A key level for a long','A key level for a short','The flip'],['Price sweeps an intermediate low that sits inside an open bullish gap.','An IML: a key level for a long','Nothing: only gaps count','The flip','A signal to buy at once'],['Price has not touched any key level since the window opened.','No key level yet: nothing to watch','A buy signal','A short signal','The flip']]);return mcq('The key level',k[0]+' What is it?',[k[1],k[2],k[3],k[4]],'The key level is where the setup starts: an unfilled gap from 15 minutes up, a rejection block, or an intermediate high or low inside an open gap (IML). Price has to trade into it or sweep it. It starts the setup; it is not the signal.')};
const flip=r=>{const long=r()<.5;return mcq('The flip',`${long?'Price has come down from the last swing high into a bullish key level':'Price has come up from the last swing low into a bearish key level'}. Inside the move are small ${long?'bearish':'bullish'} 3-minute and 5-minute gaps. What is the signal?`,[`A strong candle closes back through the highest-timeframe one of those small gaps (the inversion)`,`Price touches the key level`,`A wick pokes through the small gap`,`Price makes a new ${long?'low':'high'}`],'The key level only starts the setup. The flip, a close through the far side of the small gap with a strong candle, is the signal. A wick is not enough.')};
const highest=r=>{const k=pick(r,[['a 5-minute gap and a 3-minute gap, both open','the 5-minute gap','the 3-minute gap','either, whichever closes first','neither: both must close'],['a 3-minute gap, and a 5-minute gap that is already inverted','the 3-minute gap','the 5-minute gap','neither','both at once']]);
  return mcq('The highest gap',`Inside the leg there is ${k[0]}. Which one has to be closed through for the signal?`,[k[1],k[2],k[3],k[4]],'The highest-timeframe open 3m or 5m gap inside the leg blocks lower-timeframe inversions. Once it is inverted (or if only the lower one is open) the next one down counts.')};const flipCandle=r=>{const k=pick(r,[['A candle closes through the far side of the highest small gap with a real body and a small far-side wick.','Yes: that is displacement, a real flip','No: any candle through the gap counts','No: only a wick through the gap counts','No: the candle must be a doji'],['A candle only wicks through the small gap and closes back inside it.','No: the flip needs a close through the gap','Yes: a wick through is enough','Yes: any touch counts','Yes, if it is the first of the day'],['A candle closes through the gap but has a tiny body and a big far-side wick.','Weak: skip it, the flip needs a real body and a small far wick','A strong flip: take it','A signal to double the size','Wait for a retest']]);
  return mcq('The flip candle',k[0]+' Is it a flip?',[k[1],k[2],k[3],k[4]],'The flip is a close through the highest small gap by a candle with a real body and a small far-side wick (displacement). A wick through the gap is not enough, and a weak candle is a skip.')};
const windows=r=>{const k=pick(r,[['Asia','6:00 to 11:00 PM'],['New York AM','9:30 to 11:00 AM'],['New York PM','1:30 to 3:00 PM']]);const all=['6:00 to 11:00 PM','9:30 to 11:00 AM','1:30 to 3:00 PM','2:30 to 5:00 AM'];return mcq('Trade windows',`When is the INVERTIX ${k[0]} window (New York time)?`,[k[1],...all.filter(x=>x!==k[1])],`${k[0]}: ${k[1]}. The windows are fixed in the guide.`)};
const stages=r=>{const k=pick(r,[['Price has just touched a key level and no flip has closed yet.','Get ready: you are watching for the flip. Nothing to enter yet','Enter long at once','Enter short','The trade is over'],['A strong candle has just closed through the highest small gap and every rule passes.','Run your ticket; if it passes, enter at market at the next open','Wait for a retest','Do nothing: it is only a warning','Close your trade'],['The flip printed a while ago and price is already half a stop or more past the entry.','Skip it: it is too late to join','Join with a wider stop','Join with a bigger size','Wait for a retest'],['The flip is valid but the stop works out under 30 points.','Skip it: the setup does not meet the rules','Take the trade with a wider stop','Double the size','Remove your stop'],['A second flip forms while your first trade is still open.','It is your call: manage one trade at a time','The first trade is cancelled','Add to the first trade automatically','The window is over']]);
  return mcq('Reading the setup',k[0]+' What does it mean and what do you do?',[k[1],k[2],k[3],k[4]],'Touched a key level: get ready. Flip with every rule passing: run the ticket and enter at the next open. Half a stop or more past the entry: skip. Stop under 30 points: skip. A second flip while a trade is open: your call, one trade at a time.')};
const whoMoves=r=>mcq('The stop guide',pick(r,['Price is half a stop in profit and your stop guide says to move to your entry. Who moves your real stop order?','The stop guide has a step at half a stop in profit. When price gets there, who actually moves the order?']),['You do, by hand, once','Your broker moves it for you','Nothing: stops never move','The platform moves it for you'],'Nobody moves your orders for you. The guide tells you when; you place and move the order.');
const tooLate=r=>{const s=pick(r,[30,40,50,60,80]),p=pick(r,[.2,.35,.5,.7,1.1]),run=Math.round(s*p*10)/10,late=p>=.5;
  return mcq('Too late',`A valid INVERTIX flip printed with a ${s}-point stop, but you were away. Price has already run ${f1(run)} points past the entry and you are not in yet. What is the right call?`,late?['Skip it: price has run half a stop or more past the entry, so it is too late','Join with a wider stop','Join with a bigger size','Join and skip the stop']:['It is still fine to join, with the stop beyond the leg extreme','Skip it: any move means too late','Join with a wider stop','Wait for a retest'],late?`Half a stop is ${f1(s/2)} points. ${f1(run)} is at or past that, so it is too late. Do not chase.`:`Half a stop is ${f1(s/2)} points and price has run only ${f1(run)}, so you can still join with the stop beyond the leg extreme.`)};
const ticket=r=>{const k=pick(r,[['The flip prints at 12:15 PM New York time (no window is open).','Skip: it is outside the windows'],['The stop would be 24 points.','Skip: the stop is under 30 points'],['Price has already run half a stop past the entry.','Skip: it is too late to join'],['You have already hit your own daily loss limit.','Skip: stop for the day'],['It is not a PRIME signal and you only take PRIME ones.','Skip: it is not PRIME']]);
  return mcq('The ticket',k[0]+' You run your ticket. What do you do?',[k[1],'Take it: it looks great','Take it with half size','Wait for a retest'],'The ticket: inside a window, a stop of 30 to 90 points, not too late to join, PRIME if you trade only PRIME, inside your own loss limits. Any "no" means skip.')};
const ownLimits=r=>mcq('Your own limits',pick(r,['Nothing in INVERTIX stops you after wins, losses or a daily loss. What do you do?','Who sets your daily stop for INVERTIX trades?']),['You write your own limits (for example, stop after 2 losses) and keep them','Nothing: trade until the window ends','Let the platform stop you','Copy someone else\'s limits'],'Nothing enforces limits for you, so the limits are yours: write them down before the day and keep them.');
const primeQ=r=>{const k=pick(r,[
 ['Which of these can make a flip PRIME?','It comes early in the window, has a big flip candle, a small leg, or a V-shaped reversal','It happens on a news day','It has the widest stop','It is the third flip of the day','PRIME flips are early, forceful, tight or V-shaped.'],
 ['Which signals do you trade if you follow the default?','Only PRIME flips and PRIME early signals','Every flip','Only flips after 3 PM','Only the first flip of the week','The default is to trade only PRIME signals.'],
 ['A flip comes late in the window with a small flip candle and a long leg. What is it?','Not PRIME: skip it if you trade only PRIME','The best kind of signal','A news trade','An EARLY trade','Early, big, small leg or V-shaped are what make a signal PRIME.']]);
  return mcq('PRIME signals',k[0],[k[1],k[2],k[3],k[4]],k[5])};
const earlyQ=r=>{const k=pick(r,[
 ['When is an EARLY trade armed?','Five candles after the key level was touched, if price has closed back out of the level without closing through it','The moment the level is touched','When the flip closes','At the next window','EARLY is a separate trade for when you want to be in before the flip.'],
 ['How many EARLY trades can you take in a window?','Only the first touch of each window each day','Every touch','One a week','As many as you like','Only the first touch of each window each day is used.'],
 ['What are the EARLY target and time exit?','2 × the stop, closed after 120 minutes','The nearest gap, closed after 180 minutes','1 × the stop, closed after 30 minutes','No target, no time exit','EARLY uses a wider stop, a 2 × target and a 120-minute exit.'],
 ['Is EARLY the same trade as the flip?','No: it is a separate trade armed a few candles after the touch','Yes: it is the flip with another name','Yes: it replaces the stop guide','No: it is only for news days','The two never interfere with each other.']]);
  return mcq('INVERTIX EARLY',k[0],[k[1],k[2],k[3],k[4]],k[5])};
const hlQ=r=>{const k=pick(r,[
 ['Which window is the H/L Asia range?','6:00 to 7:00 PM','12:00 to 2:00 AM','7:00 to 9:25 AM','11:30 AM to 1:30 PM','Asia 6:00 to 7:00 PM, London 12:00 to 2:00 AM, NY AM 7:00 to 9:25 AM, NY PM 11:30 AM to 1:30 PM.'],
 ['Which window is the H/L New York AM range?','7:00 to 9:25 AM','6:00 to 7:00 PM','12:00 to 2:00 AM','11:30 AM to 1:30 PM','The NY AM range window is 7:00 to 9:25 AM, New York time.'],
 ['After one side of the range is swept, how long does it have to be confirmed?','30 candles, with an inverted gap (or a structure break plus a gap)','5 candles','All day','2 hours with a retest','If there is no confirmation in 30 candles there is no trade in that session.'],
 ['One side of the H/L range is swept but never confirms. Can you take the other side?','No: the other side is never taken in that session','Yes, at once','Yes, with a wider stop','Yes, at double size','No confirmation means no trade, and nothing else is looked for in that session.'],
 ['How far must a side be swept before H/L counts it?','By at least the displacement setting, 10 points by default','Any amount','50 points','Only by a wick of 1 point','A sweep has to be at least 10 points.'],
 ['What is the default H/L take profit and break-even move?','Take profit 2 × the stop (or the opposite side of the range), and one break-even move at 1 × the stop','Take profit 1 × the stop, no break-even','Take profit 5 × the stop','No take profit, hold overnight','H/L has one take profit and one break-even move at 1 × the stop.']]);
  return mcq('H/L',k[0],[k[1],k[2],k[3],k[4]],k[5])};
const po3Q=r=>{const k=pick(r,[
 ['At which times are the 4-hour opens PO3 uses?','6 AM, 10 AM, 2 PM, 6 PM and 10 PM','9:30 AM only','Every hour','Midnight only','PO3 works from each 4-hour open.'],
 ['How far must price be pushed beyond the open for PO3?','At least 15 points, into a real zone: an open 1H gap, or the previous day\'s high or low','Any distance','5 points','100 points','The push has to reach a real zone, not just wander past the open.'],
 ['What confirms a PO3 trade?','A 1-minute inverted gap (or a CISD)','A news candle','A retest of the open','Nothing: enter at the open','After the push into the zone, a 1-minute inversion or CISD confirms.'],
 ['No confirmation arrives within 90 minutes of a PO3 push. What happens?','No trade: nothing new is looked for until the next session','Enter anyway','Take the other side','Wait all day','No confirmation within 90 minutes or by the end of the 4H window means no trade.'],
 ['Price is pushed up first, then down, around the same open. Which side does PO3 take?','Only the first side that was pushed','Both sides','The second side','Neither','The first side that is pushed is the only side taken that session.'],
 ['What is the default PO3 take profit?','2 × the stop, or back to the open line, with one break-even move','1 × the stop','5 × the stop','No target','One take profit and one break-even move.']]);
  return mcq('PO3',k[0],[k[1],k[2],k[3],k[4]],k[5])};
const newsQ=r=>{const k=pick(r,[
 ['When does the news fade take a trade?','When the one-minute news candle is a big spike (at least 6 × the recent average candle): the trade goes the opposite way at the next open','On every news release','Only when the candle is small','In the same direction as the spike','You fade the spike, not follow it.'],
 ['How long does a news fade stay open?','120 minutes, which carries it through the 9:30 open','5 minutes','Until the close','30 minutes','Leave it alone through the open: shorter holds do not work.'],
 ['What are the news fade stop and take profit?','Stop 1 × the news candle\'s range, take profit 2 × the stop','Stop 10 points, take profit 40','Stop 1 × the range, take profit 1 × the stop','No stop','The stop is the size of the news candle.'],
 ['Which news times does the fade work with?','8:30 AM data (CPI, PPI, jobs and so on), and the 2:00 PM FOMC statement','Only 9:30 AM','Only weekends','Any time','The news time is the candle you are fading.'],
 ['Why size the news fade so that a slipping stop is acceptable?','The 9:30 open is the most violent part of the trade and stops can slip past your price','Stops never slip','Because it is a small trade','The broker pays slippage','Size it so a stop slipping a little further is acceptable.']]);
  return mcq('News fade',k[0],[k[1],k[2],k[3],k[4]],k[5])};
const fomcQ=r=>{const k=pick(r,[
 ['How do you recognise an FOMC day?','The 2:00 PM candle is a big spike (or you decide it is an FOMC day yourself)','The 8:30 AM candle is small','It is a Friday','There is no way','No dates to type: the spike shows it.'],
 ['What is the default FOMC evening trade?','Buy the 6:30 PM open (or trade the break of the 6:00 to 6:30 PM opening range either way)','Sell the 9:30 AM open','Trade the 2:00 PM spike','Hold overnight with no stop','There are two options: the 6:30 PM open, or the break of the opening range.'],
 ['When does the FOMC evening trade close?','At 3 AM','At 4 PM','After 5 minutes','Never','The trade closes at 3 AM if the stop and target were not hit.'],
 ['How are the FOMC evening stop and target set?','From the typical day\'s range','Always 10 and 40','From the news candle','From the 4H open','Stop and target come from the typical day\'s range.']]);
  return mcq('FOMC evening',k[0],[k[1],k[2],k[3],k[4]],k[5])};
const sectionQ=r=>{const k=pick(r,[
 ['Which section trades the break of the 6 PM opening range on an FOMC day?','FOMC evening','H/L','PO3','Key-level flip','FOMC evening trades the 6:30 PM open or the break of the 6:00 to 6:30 PM range.'],
 ['Which section sweeps a session\'s high or low and confirms with an inverted gap?','H/L','News fade','EARLY','FOMC evening','H/L waits for a swept side and an inversion.'],
 ['Which section pushes price beyond a 4-hour open into a real zone?','PO3','H/L','News fade','EARLY','PO3 is built around the 4H opens.'],
 ['Which section fades the one-minute news candle?','News fade','PO3','H/L','The flip','The news fade goes the opposite way of the spike.'],
 ['Which section is a separate trade a few candles after the key level was touched?','EARLY','The flip','PO3','H/L','EARLY is for being in before the flip.']]);
  return mcq('The sections',k[0],[k[1],k[2],k[3],k[4]],k[5])};
const invOrder=()=>({kind:'order',topic:'INVERTIX',q:'Put the INVERTIX flip steps in order.',steps:['Price trades into (or sweeps) a key level: a 15m-or-higher gap, a rejection block or an intermediate high or low in a gap','The manipulation leg and its small 3m / 5m gaps are in place','A strong candle closes through the highest small gap: the flip','The ticket passes: window, stop 30 to 90 points, not too late to join, own limits','Market entry at the next open, stop beyond the leg extreme, target the nearest gap'],why:'Key level, then the leg, then the flip, then the ticket, then the order. If any step is missing, there is no trade.'});
/* ---------- m43 · the idea and the sections ---------- */
quick({id:'m43',o:15.61,ph:7,t:'INVERTIX: The Idea and the Sections',out:'Explain how an INVERTIX flip trade is built, name the six trade sections, and know the windows and the optional bias.',
 ls:['The first model: manipulation, then reversal','The pieces of a flip trade','One strategy, six sections','The windows','Your bias for the day (optional)','Long and short are mirrors'],
 task:'On a 1-minute NQ chart in replay, find one move where price ran into an unfilled 15-minute gap, then closed back through a small gap inside the move. Write the pieces in order for that trade: key level, leg, flip, entry, stop and target. Then write which of the six sections each of two other setups you can find would belong to.',
 learn:[
  {t:'The first model: manipulation, then reversal',h:`<p><b>INVERTIX</b> is the first trading model you learn in the FLOWMTD school. It is an <b>inverse fair value gap (IFVG) model</b> for NQ and MNQ, used on the <b>1-minute chart</b>. The idea: price grabs liquidity (the <b>manipulation</b>), runs into a higher-timeframe level (the <b>key level</b>), and then reverses (the <b>distribution</b>). You wait for the reversal to be <b>confirmed by an inversion</b> and only then take the trade.</p><p>The word <b>INVERTIX</b> comes from <b>inversion</b>: the moment a small gap flips its role. That moment is called the <b>flip</b>.</p>`},
  {t:'The pieces of a flip trade',h:tblx(['Piece','What it is'],[['Key level','A higher-timeframe fair value gap, a rejection block, or an intermediate high or low swept inside a gap. Price has to trade into it.'],['Manipulation leg','The move into the key level. Your stop sits beyond its extreme.'],['The flip','The highest-timeframe small gap (3 or 5 minute) in the leg is closed through by a candle with a real body and a small far-side wick.'],['Entry','The open of the next candle after the flip. No waiting for a retest.'],['Stop','Beyond the extreme of the manipulation leg. Under 30 points is skipped; over 90 is tightened to 90.'],['Target','The nearest unfilled 5-minute or 15-minute gap in your direction, but never closer than 1 × the stop.']])},
  {t:'One strategy, six sections',h:`<p>INVERTIX is one strategy with separate trade sections. Each has its own idea, and the sections never interfere with each other. Learn the main section first.</p>${tblx(['Section','Idea','Where to start'],[['INVERTIX (the flip)','Price trades into a higher-timeframe key level, then a small gap is closed through the other way. Enter at the next open.','Main section'],['INVERTIX EARLY','A second, separate trade a few candles after the key level was touched, for when you want to be in before the flip.','Main section'],['H/L','A session\'s high or low is swept, then an inverted gap (or a structure break) confirms. Trade back toward the other side.','Optional'],['PO3','At each 4-hour open price is pushed beyond the open into a real zone, then confirms.','Optional'],['News fade','Fade the one-minute news candle (8:30 CPI, PPI, jobs and so on).','Optional'],['FOMC evening','On an FOMC day, trade the 6 PM opening range or the 6:30 PM open.','Optional']])}<p>Modules 5 to 7 teach EARLY and PRIME, H/L and PO3, and the news fade and FOMC evening trade.</p>`},
  {t:'The windows',h:tblx(['Window','New York time'],[['Asia','6:00 to 11:00 PM'],['New York AM','9:30 to 11:00 AM'],['New York PM','1:30 to 3:00 PM']])+`<p>The windows are fixed. A flip outside them is not a flip trade.</p>`},
  {t:'Your bias for the day (optional)',h:`<p>You can pick a bias for the day: <b>neutral</b> (both directions), <b>longs only</b> or <b>shorts only</b>. It is only your opinion, you choose it each day, and it only decides which setups you watch. If you use one, write it down <b>before you look for trades</b>, with one line of why.</p>`},
  {t:'Long and short are mirrors',h:`<p>Everything is taught for shorts and longs by mirroring. A bearish key level above price is for shorts and a bullish key level below price is for longs. Every "high" becomes a "low", every "bullish" becomes "bearish".</p>`}],
 recall:rc('Building Daily Bias','What is the first step in building a daily bias?',['Identify the higher-time-frame trend','Find an entry candle','Pick a stop size','Read the news'],'INVERTIX also starts with where price is and where it is heading.'),
 steps:[['<b>The pieces.</b>',tblx(['Piece','Short example'],[['Key level','Price pushes up into an unfilled bearish 15m gap'],['Leg','From the last swing low up into the gap'],['Flip','A strong candle closes below the highest small bullish gap in the leg'],['Entry','Market at the next open'],['Stop','Above the leg high (30 to 90 pts)'],['Target','The near edge of the nearest unfilled gap below']])],['<b>The sections.</b>',tblx(['Section','Idea in four words'],[['INVERTIX','Key level, then flip'],['EARLY','In before the flip'],['H/L','Swept session extreme'],['PO3','Push past the 4H open'],['News fade','Fade the spike'],['FOMC evening','Trade the 6 PM range']])]],
 gens:[sectionQ,keyLevel,flip,windows],
 bank:BANKS('INVERTIX',[
  ['What chart do you use INVERTIX on?',['The 1-minute chart','The daily chart','The 4-hour chart','The weekly chart'],'INVERTIX is built for the 1-minute chart.'],
  ['What does "INVERTIX" refer to?',['An inversion: a gap flipping its role','A news release','A stop type','A time of day'],'The flip is an inversion.'],
  ['Price grabs liquidity, runs into a higher-timeframe level, then reverses. What is the first part called?',['The manipulation','The distribution','The retest','The target'],'Manipulation, then the reversal (distribution).'],
  ['What is the signal in the main section?',['A strong close through the highest small gap in the leg: the flip','A wick into the key level','A new low','The open'],'The flip.'],
  ['Where is the entry?',['At the open of the next candle (market)','At the key level with a limit','At a retest of the gap','At the close of the day'],'There is no retest.'],
  ['What happens to a stop under 30 points?',['The setup is skipped','It is widened to 30','It is removed','It is doubled'],'Under 30 is skipped; over 90 is tightened to 90.'],
  ['How many trade sections does INVERTIX have?',['Six: the flip, EARLY, H/L, PO3, news fade and FOMC evening','One','Two','Ten'],'They never interfere with each other.'],
  ['When is the New York AM window?',['9:30 to 11:00 AM','1:30 to 3:00 PM','6:00 to 11:00 PM','2:30 to 5:00 AM'],'New York time.'],
  ['What does your bias for the day do?',['Only decides which setups you watch','Places your orders','Sets your stop','Is required'],'It is optional and only your opinion.'],
  ['Which comes first in a flip trade?',['The key level','The flip','The entry','The target'],'Key level, leg, flip, then the order.']]),
 examDesc:'The pieces in order, the six sections, the windows and the optional bias.'});
/* ---------- m44 · the key level ---------- */
quick({id:'m44',o:15.62,ph:7,t:'INVERTIX: The Key Level',out:'Find the key level that starts a setup, and know when you are only watching.',
 ls:['The key level','Fair value gaps from 15 minutes up','Rejection blocks','The intermediate high or low','Touched, and now watching','The leg'],
 task:'On a 1-minute chart of MNQ1! in replay, find three places where price ran into a 15-minute-or-higher gap, a rejection block or an intermediate high or low inside an open gap. Mark each one with a box and its name, and mark the swing the move started from.',
 learn:[
  {t:'The key level',h:`<p>An INVERTIX setup begins when price <b>trades into</b> a key level. There are three kinds:</p>${tblx(['Key level','What it is'],[['Fair value gap','An unfilled gap on the 15-minute, 30-minute, 1-hour, 4-hour or Daily chart'],['Rejection block','A wick sitting in a gap, rejected'],['Intermediate high or low','A small swing inside an open gap, swept by price']])}<p>A bearish key level above price is for shorts; a bullish key level below price is for longs. A 5-minute gap is too small to be a key level.</p>`},
  {t:'Fair value gaps from 15 minutes up',h:`<p>The most common key level is an <b>unfilled fair value gap</b> on a higher timeframe. For a long, price drops down into a bullish gap; for a short, price pushes up into a bearish gap. Mark it with an <b>outlined box and its name</b>, for example "15m FVG".</p>`},
  {t:'Rejection blocks',h:`<p>A <b>rejection block</b> is a candle with a long wick sitting in a gap and being rejected. It counts as a key level because price was pushed into the gap and turned.</p>`},
  {t:'The intermediate high or low',h:`<p>An <b>intermediate high or low</b> is a small swing that sits <b>inside an open gap</b>. When price sweeps it, that is a key level too. Mark it yourself and check it in replay.</p>`},
  {t:'Touched, and now watching',h:`<p>Price has to <b>trade into</b> the key level. You are now <b>watching long</b> or <b>watching short</b>: write down the level, the leg and what you are waiting for. Watching means <b>get ready</b>. There is nothing to enter yet: the flip is the signal.</p>`},
  {t:'The leg',h:`<p>The <b>manipulation leg</b> is the move into the key level, from the last swing to the level. Inside it price leaves small gaps. Your stop will sit beyond the extreme of this leg.</p>`}],
 recall:rc('INVERTIX: The Idea and the Sections','What is the signal in the main section?',['A strong close through the highest small gap in the leg: the flip','A wick into the key level','A new low','The open'],'The key level only starts the setup.'),
 steps:[['<b>Key levels.</b>',tblx(['Type','Where'],[['FVG','15m, 30m, 1H, 4H, Daily'],['Rejection block','A wick sitting in a gap'],['Intermediate high or low','A small swing swept inside an open gap']])],['<b>The stages.</b>',tblx(['Stage','Means'],[['Price trades into a level','A key level is touched'],['Watching long / short','Get ready: nothing to enter yet'],['The flip','The signal: run the ticket']])]],
 gens:[keyLevel,stages,highest],
 bank:BANKS('The key level',[
  ['Which of these can be a key level?',['An unfilled 15-minute gap','A 3-minute gap','The daily open','A round number'],'15 minutes and up, a rejection block or an intermediate high or low.'],
  ['A rejection block is…',['A wick sitting in a gap that is rejected','A candle gap','A news candle','A stop order'],'A wick in a gap, rejected.'],
  ['An intermediate high or low is…',['A small swing inside an open gap that price sweeps','A type of order','The daily low','A news time'],'It sits within a gap.'],
  ['What starts an INVERTIX setup?',['Price trading into a key level','A news release','The window opening','A green candle'],'The key level.'],
  ['For a long, price runs into…',['A bullish key level below','A bearish key level above','The previous high','Nothing'],'Longs come down into a bullish level.'],
  ['Watching long means…',['A key level was touched: get ready, nothing to enter yet','Enter long now','The trade is over','The stop was hit'],'Get ready. The flip is the signal.'],
  ['Which timeframes can a key level fair value gap be on?',['15m, 30m, 1H, 4H or Daily','1-minute only','3-minute only','Any gap at all'],'A 5-minute gap is too small.'],
  ['What is the manipulation leg?',['The move into the key level','The candle after the flip','The target gap','The window'],'Your stop sits beyond its extreme.'],
  ['When should you write your bias for the day, if you use one?',['Before you look for trades','After the first signal','At the end of the week','Never'],'Bias first, with one line why.']]),
 examDesc:'Finding the key level, watching, and the leg.'});
/* ---------- m45 · the flip, entry and stop ---------- */
quick({id:'m45',o:15.63,ph:7,t:'INVERTIX: The Flip, Entry and Stop',out:'Find the flip, judge the candle, and place the entry and stop.',
 ls:['The leg and its small gaps','The highest gap blocks the lower ones','The flip: a close through the gap','The flip candle','Entry at the next open','The stop: 30 to 90 points','When to skip'],
 task:'On a 1-minute NQ chart in replay, find three flips. For each, mark the highest small gap inside the leg, the candle that closed through it, and say whether that candle has a real body and a small far-side wick. Measure the stop from the entry to the leg extreme.',
 learn:[
  {t:'The leg and its small gaps',h:`<p>The <b>leg</b> runs from the last swing to the key level. Inside it price leaves small gaps: <b>bearish</b> ones on the way down for a long, <b>bullish</b> ones on the way up for a short. You look at the <b>3-minute and 5-minute</b> gaps.</p>`},
  {t:'The highest gap blocks the lower ones',h:`<p>If a 5-minute gap and a 3-minute gap are both open inside the leg, the <b>5-minute gap has to be closed through first</b>: the highest-timeframe open gap blocks lower-timeframe inversions.</p>`},
  {t:'The flip: a close through the gap',h:`<p>The <b>flip</b> is a candle that <b>closes through the far side</b> of that gap: above it for a long, below it for a short. A wick is not enough. When it happens and every rule passes, you have a <b>signal</b>. The projected entry, stop and target are worked out straight away.</p>`},
  {t:'The flip candle',h:`<p>The inverting candle has to show <b>displacement</b>: a <b>real body</b> and a <b>small wick on the far side</b>, the side you are trading toward. A candle that closes through the gap with a tiny body or a big rejection wick is not a flip.</p>${key('<p>If every box is ticked except one, skip it. The rules are the model.</p>')}`},
  {t:'Entry at the next open',h:`<p>Entry is the <b>open of the next candle</b> after the flip: a market order. There is <b>no waiting for a retest</b>.</p>`},
  {t:'The stop: 30 to 90 points',h:`<p>The <b>stop</b> goes beyond the extreme of the manipulation leg (below its low for a long). The distance decides what you do:</p>${tblx(['Distance to the extreme','What you do'],[['Under 30 points','The setup is skipped'],['30 to 90 points','The stop stays there'],['Over 90 points','The stop is tightened to 90 points']])}`},
  {t:'When to skip',h:`<p>Skip the setup when the flip candle is weak, the stop is under 30 points, or the signal is outside your windows. Write down the reason and move on. Skipping is part of the plan.</p>`}],
 recall:rc('INVERTIX: The Key Level','Which of these can be a key level?',['An unfilled 15-minute gap','A 3-minute gap','The daily open','A round number'],'The key level is a 15-minute-or-higher gap, a rejection block or an intermediate high or low.'),
 steps:[['<b>The flip candle.</b>',tblx(['Part','Needs'],[['Close','Through the far side of the highest small gap'],['Body','A real body'],['Far-side wick','Small']])],['<b>The stop.</b>',tblx(['Distance','Result'],[['Under 30','Skipped'],['30 to 90','Used'],['Over 90','Tightened to 90']])]],
 gens:[flipCandle,stopRule,highest,flip],
 bank:BANKS('The flip, entry and stop',[
  ['What is the flip?',['A candle closing through the far side of the highest small gap in the leg','A wick through the key level','A new swing','The open of the next candle'],'The inversion of the gap.'],
  ['Which small gaps do you watch?',['3-minute and 5-minute','1-minute only','Daily','15-minute only'],'The highest open 3m or 5m gap in the leg.'],
  ['A 5-minute gap and a 3-minute gap are both open in the leg. Which closes first for the signal?',['The 5-minute gap','The 3-minute gap','Either','Neither'],'The highest-timeframe open gap blocks the lower ones.'],
  ['What does the flip candle need?',['A real body and a small far-side wick','A long wick','A doji','A news spike'],'Displacement.'],
  ['Does a wick through the gap count as the flip?',['No: it has to be a close','Yes','Only on the 1-minute','Only in Asia'],'Closes count, wicks do not.'],
  ['Where is the entry?',['At the open of the next candle','At a retest of the gap','At the key level','At the swing'],'Market at the next open.'],
  ['Where does the stop go on a long?',['Beyond the extreme of the manipulation leg','Above the flip candle','At the key level top','At the entry'],'Beyond the leg extreme.'],
  ['The extreme of the leg is 85 points from your entry. The stop is…',['85 points','Tightened to 60','Removed','Doubled'],'Over 90 would be tightened to 90; 85 stays.'],
  ['The extreme of the leg is 22 points from your entry. What happens?',['The setup is skipped: under 30 points','The stop is widened to 30','The stop is 22 points','The stop is removed'],'Stops under 30 points are skipped, not widened.'],
  ['What do you do when a setup does not meet the rules?',['Skip it and note the reason','Enter anyway','Widen the stop','Wait for the window to close'],'Skipping is part of the plan.']]),
 examDesc:'Finding the flip, judging the candle, and the entry and stop rules.'});
/* ---------- m46 · target, break-even and size ---------- */
quick({id:'m46',o:15.64,ph:7,t:'INVERTIX: Target, Break-even and Size',out:'Place the target, move the stop once, know when it is too late, and size the trade.',
 ls:['The target','Other target modes','The stop guide: break-even at half a stop','How a trade ends','Too late to join','Your own limits','Contracts'],
 task:'Choose your contract and your risk in dollars. Write down your own daily loss limits, how many MNQ a 40-point stop gives you, and for one past setup the target, the half-stop level where you would move your stop to your entry, and the price at which it would have been too late to join.',
 learn:[
  {t:'The target',h:`<p>The default <b>target</b> is the <b>nearest unfilled 5-minute or 15-minute gap</b> in your direction, but <b>never closer than 1 × the stop</b>. If the nearest gap is too close, the target is pushed out to the distance of your stop.</p>`},
  {t:'Other target modes',h:`<p>Instead of the nearest gap you can aim for a <b>higher-timeframe gap</b>, or for <b>multiples of the stop</b>: TP1, TP2 and TP3. Pick one way before the trade and keep it.</p>`},
  {t:'The stop guide: break-even at half a stop',h:`<p>When price is <b>0.5 × the stop in profit</b>, you move your stop to your <b>entry</b>. Once, and then leave it.</p>${tblx(['Stop','Price is in profit by','Move your stop to'],[['40 points','20 points','Your entry'],['60 points','30 points','Your entry']])}<p>Nothing moves your orders for you: you place the new stop yourself.</p>`},
  {t:'How a trade ends',h:`<p>A trade ends at the <b>target</b>, at the <b>stop</b> (or your break-even stop), or <b>180 minutes after the entry</b> if neither was hit. Never carry a trade over a weekend or holiday.</p>`},
  {t:'Too late to join',h:`<p>If price has already run <b>0.5 × the stop</b> past your entry and you are not in, it is <b>too late</b>. Skip it. Do not chase with a wider stop or a bigger size.</p>`},
  {t:'Your own limits',h:`<p>There are no account or loss-limit rules built in. The limits are yours. Write them down before the day, for example "stop after 2 losses" or "stop at −$600", and keep them. On an evaluation account keep your risk small.</p>`},
  {t:'Contracts',h:key('<p><b>Contracts = risk in dollars ÷ (stop in points × dollars per point)</b>, rounded down. Never take a trade whose real risk is more than the risk you chose. If 1 MNQ is already too much, skip it.</p>','The formula')+tblx(['Risk $500','MNQ ($2 a point)'],[['30-point stop','8'],['40-point stop','6'],['90-point stop','2']])}],
 recall:rc('INVERTIX: The Flip, Entry and Stop','What happens to a stop of 22 points?',['The setup is skipped','It is widened to 30','It stays at 22','It is removed'],'Under 30 is skipped; over 90 is tightened to 90.'),
 steps:[['<b>The target.</b>',tblx(['Stop','Nearest gap','Target'],[['40','28','40 (never closer than 1 × the stop)'],['40','60','60 (the gap)'],['50','90','90 (the gap)']])],['<b>The stop guide.</b>',tblx(['Stop','Move to entry when price is in profit by'],[['30','15'],['40','20'],['80','40']])]],
 gens:[targetRule,beStep,tooLate,contracts,windows,whoMoves,ownLimits],
 bank:BANKS('Target, break-even and size',[
  ['What is the default target?',['The nearest unfilled 5m or 15m gap in your direction, never closer than 1 × the stop','Always 2R','The previous day high','A fixed 15 points'],'The nearest gap, with a 1 × stop minimum.'],
  ['The nearest gap is closer than the stop. What is the target?',['Pushed out to 1 × the stop','The gap anyway','Removed','Doubled'],'Never closer than 1 × the stop.'],
  ['Which other target modes exist?',['A higher-timeframe gap, or multiples of the stop (TP1, TP2, TP3)','Only a fixed 15 points','The daily low','None'],'Pick one before the trade.'],
  ['When do you move your stop to your entry?',['When price is half a stop (0.5 × the stop) in profit','After 5 minutes','At +2R','Never'],'Once, at half a stop in profit.'],
  ['After how long does a trade end on the time exit?',['180 minutes after the entry','5 minutes','24 hours','Never'],'If neither the stop nor the target was hit.'],
  ['When is it too late to join?',['Price has run 0.5 × the stop past your entry and you are not in','Any move at all','After 3 candles','After the window ends'],'Skip it. Do not chase.'],
  ['Who places and moves the stop order?',['You','Your charting platform','Your broker automatically','Your prop firm'],'Nobody moves your orders but you.'],
  ['Who sets your loss limits for INVERTIX trades?',['You do','Your charting platform','Your broker','Nobody'],'Nothing stops you automatically: write your own limits.'],
  ['Contracts =',['Risk in dollars ÷ (stop points × dollars per point), rounded down','Target ÷ stop','Account ÷ 1000','Risk × stop'],'Minimum 1.'],
  ['1 MNQ is already more risk than you chose. What do you do?',['Skip the trade','Trade 1 MNQ anyway','Use a wider stop','Trade 2'],'Never take a trade whose real risk is more than the risk you chose.']]),
 examDesc:'The target, half-stop break-even, the time exit, too late, your own limits and sizing.'});
/* ---------- m51 · PRIME and EARLY ---------- */
quick({id:'m51',o:15.645,ph:7,t:'INVERTIX: PRIME Signals and EARLY',out:'Pick out the best signals, and take the separate EARLY trade before the flip.',
 ls:['PRIME signals','Why only PRIME','INVERTIX EARLY','The EARLY trade, step by step','EARLY or the flip'],
 task:'In replay, mark five flips in the same window. For each, say whether it is early in the window, whether the flip candle is big, whether the leg is small, and whether the reversal is V-shaped. Mark which ones are PRIME. Then find one key-level touch where price closed back out of the level five candles later, and write the EARLY entry, stop and target.',
 learn:[
  {t:'PRIME signals',h:`<p>The best signals carry the word <b>PRIME</b>. A flip can earn it from any of these:</p>${tblx(['Sign','What it looks like'],[['Early in the window','The flip comes soon after the window opens'],['A big flip candle','The candle that closes through the gap is large and forceful'],['A small leg','The move into the key level was short, so the stop is tight'],['A V-shaped reversal','Price turns sharply at the level instead of drifting']])}`},
  {t:'Why only PRIME',h:`<p>By default you trade only <b>PRIME flips</b> and <b>PRIME early signals</b>. A flip that is late, weak and drawn out can still meet the rules, but it is not one of the best, and you skip it unless you have chosen to trade every flip.</p>`},
  {t:'INVERTIX EARLY',h:`<p><b>EARLY</b> is a second, separate trade a few candles after the key level was touched, for when you want to be in before the flip. It never interferes with the flip trade.</p>`},
  {t:'The EARLY trade, step by step',h:tblx(['Step','Rule'],[['Arm','Five candles after the key level was touched, if price has closed back out of the level without closing through it, an early trade is armed for the next open'],['Stop','Wider than a flip stop: a quarter of the typical day\'s range, up to 90 points'],['Target','2 × the stop'],['Time exit','Closes after 120 minutes'],['How often','Only the first touch of each window each day']])},
  {t:'EARLY or the flip',h:`<p>EARLY gets you in earlier with a wider stop. The flip waits for confirmation and has a tighter stop. They are separate trades, so decide before the window how you will treat each, and never add one to the other without a plan.</p>`}],
 recall:rc('INVERTIX: Target, Break-even and Size','When do you move your stop to your entry?',['When price is half a stop in profit','After 5 minutes','At +2R','Never'],'Once, at half a stop.'),
 steps:[['<b>What makes a flip PRIME.</b>',tblx(['Sign','Yes if'],[['Early','Soon after the window opens'],['Big flip candle','Large, forceful'],['Small leg','Short move into the level'],['V-shaped reversal','Sharp turn at the level']])],['<b>EARLY at a glance.</b>',tblx(['Item','Rule'],[['Armed','5 candles after the touch, price back out of the level'],['Stop','1/4 of the typical day\'s range, up to 90'],['Target','2 × stop'],['Exit','120 minutes'],['Limit','First touch of each window']])]],
 gens:[primeQ,earlyQ,earlyStop,stages],
 bank:BANKS('PRIME and EARLY',[
  ['What makes a flip PRIME?',['It comes early in the window, has a big flip candle, a small leg, or a V-shaped reversal','It is on a news day','It has the widest stop','It is the third flip of the day'],'PRIME flips are early, forceful, tight or V-shaped.'],
  ['Which signals do you trade by default?',['Only PRIME flips and PRIME early signals','Every flip','Only flips after 3 PM','Only the first flip of the week'],'The default is PRIME only.'],
  ['When is an EARLY trade armed?',['Five candles after the touch, if price has closed back out of the level without closing through it','The moment the level is touched','When the flip closes','At the next window'],'It is a separate trade.'],
  ['What stop does EARLY use?',['A quarter of the typical day\'s range, up to 90 points','Always 10 points','The leg extreme','No stop'],'Wider than the flip stop.'],
  ['What target does EARLY use?',['2 × the stop','The nearest gap','1 × the stop','No target'],'2 × the stop.'],
  ['After how long does an EARLY trade close?',['120 minutes','180 minutes','5 minutes','Never'],'The time exit is 120 minutes.'],
  ['How many EARLY trades per window per day?',['Only the first touch of each window each day','Every touch','Two','As many as you like'],'Only the first touch.'],
  ['Is EARLY the same trade as the flip?',['No: it is a separate trade','Yes','It replaces the stop','Only on news days'],'They never interfere with each other.']]),
 examDesc:'PRIME signs, why only PRIME, and the EARLY trade rules.'});
/* ---------- m52 · H/L and PO3 ---------- */
quick({id:'m52',o:15.646,ph:7,t:'INVERTIX: H/L and PO3',out:'Trade a swept session extreme (H/L) and a push past a 4-hour open (PO3), each with its own rules.',
 ls:['H/L: the idea and the range windows','H/L: the sweep and the 30-candle confirmation','H/L: entry, stop and target','PO3: the 4-hour opens','PO3: the push, the zone and the confirmation','PO3: stop, target and one side only'],
 task:'In replay, mark the Asia range (6:00 to 7:00 PM) and the NY AM range (7:00 to 9:25 AM) for three days. For each day, note which side was swept first and by how many points, whether an inverted gap confirmed within 30 candles, and the entry, stop and 2 × take profit. Then mark the 10 AM open and say whether price was pushed at least 15 points beyond it into an open 1H gap or the previous day\'s high or low.',
 learn:[
  {t:'H/L: the idea and the range windows',h:`<p><b>H/L</b> is optional. A session\'s high or low is swept, then an inverted gap (or a structure break) confirms, and you trade back toward the other side. Each session has a range window:</p>${tblx(['Session','Range window (New York)'],[['Asia','6:00 to 7:00 PM'],['London','12:00 to 2:00 AM'],['NY AM','7:00 to 9:25 AM'],['NY PM','11:30 AM to 1:30 PM']])}<p>Draw the high and the low of the window as dotted lines and label them with the session and its time.</p>`},
  {t:'H/L: the sweep and the 30-candle confirmation',h:`<ol><li>After the window closes there is no cutoff time: you watch for one side to be swept by at least the <b>displacement</b>, <b>10 points</b> by default.</li><li>Once a side is swept it has <b>30 candles</b> to confirm with an <b>inverted gap</b> (or a structure break plus a gap).</li><li>If it does not confirm, there is <b>no trade</b> and nothing else is looked for in that session. The other side is <b>never taken</b>.</li></ol>`},
  {t:'H/L: entry, stop and target',h:tblx(['Item','Rule'],[['Entry','At the next open after the confirmation'],['Stop','Beyond the swept extreme'],['Take profit','One take profit: 2 × the stop by default, or the opposite side of the range'],['Break-even','One move, at 1 × the stop']])},
  {t:'PO3: the 4-hour opens',h:`<p><b>PO3</b> is optional. It works from each <b>4-hour open</b>: <b>6 AM, 10 AM, 2 PM, 6 PM and 10 PM</b>. Draw the open price as a dashed line and label it, for example "PO3 · 10 AM open".</p>`},
  {t:'PO3: the push, the zone and the confirmation',h:`<ol><li>Price must be pushed at least <b>15 points beyond the open</b> (down for a long, up for a short) into a <b>real zone</b>: an open 1H gap, or the previous day\'s high or low.</li><li>Then a <b>1-minute inverted gap</b> (or a CISD) confirms.</li><li>No confirmation within <b>90 minutes</b>, or by the end of the 4H window, means <b>no trade</b>.</li></ol>`},
  {t:'PO3: stop, target and one side only',h:`<p>The <b>first side that is pushed is the only side taken</b> that session. The stop goes beyond the manipulation extreme. There is one take profit: <b>2 × the stop</b>, or back to the open line. There is one break-even move.</p>`}],
 recall:rc('INVERTIX: PRIME Signals and EARLY','When is an EARLY trade armed?',['Five candles after the touch, if price has closed back out of the level without closing through it','The moment the level is touched','When the flip closes','At the next window'],'EARLY is a separate trade.'),
 steps:[['<b>H/L in order.</b>',tblx(['Step','What happens'],[['1','The window closes; draw its high and low'],['2','One side is swept by 10 points or more'],['3','An inverted gap confirms within 30 candles, or no trade'],['4','Enter at the next open; stop beyond the swept extreme'],['5','Take profit at 2 × the stop; one break-even move at 1 × the stop']])],['<b>PO3 in order.</b>',tblx(['Step','What happens'],[['1','Mark the 4-hour open'],['2','Price is pushed 15+ points beyond it into a real zone'],['3','A 1-minute inversion or CISD confirms within 90 minutes'],['4','First side only; stop beyond the extreme'],['5','Take profit at 2 × the stop or the open line']])]],
 gens:[hlQ,po3Q,hlTarget,sectionQ],
 bank:BANKS('H/L and PO3',[
  ['Which window is the H/L Asia range?',['6:00 to 7:00 PM','12:00 to 2:00 AM','7:00 to 9:25 AM','11:30 AM to 1:30 PM'],'Asia is 6:00 to 7:00 PM.'],
  ['How far must a side be swept for H/L?',['At least 10 points by default','Any amount','50 points','Never'],'The displacement.'],
  ['How long does a swept side have to confirm?',['30 candles','5 candles','All day','2 hours'],'With an inverted gap, or a structure break plus a gap.'],
  ['No confirmation arrives for H/L. What do you do?',['No trade: nothing else in that session','Take the other side','Enter anyway','Widen the stop'],'The other side is never taken.'],
  ['What is the default H/L take profit?',['2 × the stop, or the opposite side of the range','1 × the stop','5 × the stop','None'],'One take profit, one break-even move at 1 × the stop.'],
  ['At which times are the 4-hour opens PO3 uses?',['6 AM, 10 AM, 2 PM, 6 PM and 10 PM','9:30 AM only','Every hour','Midnight only'],'Each 4-hour open.'],
  ['How far must price be pushed beyond the open for PO3?',['At least 15 points into a real zone','Any amount','5 points','100 points'],'An open 1H gap, or the previous day\'s high or low.'],
  ['What confirms PO3?',['A 1-minute inverted gap or a CISD','A news candle','A retest of the open','Nothing'],'Then you trade.'],
  ['How long does PO3 wait for the confirmation?',['90 minutes, or until the 4H window ends','5 minutes','All day','1 hour only'],'After that: no trade.'],
  ['Which PO3 side do you take?',['Only the first side that was pushed','Both sides','The second side','Neither'],'One side per session.']]),
 examDesc:'The H/L range windows and sweep rules, and the PO3 4-hour opens, push, confirmation and targets.'});
/* ---------- m53 · news fade and FOMC evening ---------- */
quick({id:'m53',o:15.647,ph:7,t:'INVERTIX: News Fade and FOMC Evening',out:'Fade a big news candle and trade the FOMC evening, with their own stops, targets and timing.',
 ls:['The news fade','Stop, target and hold','Why the 9:30 open matters','The FOMC evening trade','When it closes'],
 task:'Find the last 8:30 AM data release in replay. Mark the 1-minute news candle, work out its range and whether it was at least 6 times the recent average candle, then write the entry (the next open, the opposite way), the stop (1 × the range) and the take profit (2 × the stop). Then find the last FOMC day and note what the 2:00 PM candle did and where the 6:00 to 6:30 PM opening range was.',
 learn:[
  {t:'The news fade',h:`<p>The <b>news fade</b> is optional. You fade the one-minute news candle: 8:30 AM data such as CPI, PPI and jobs, and the 2:00 PM statement on FOMC days also works.</p><ol><li>Note the time of the news candle (8:30 New York by default).</li><li>If that one-minute candle is a big spike, <b>at least 6 × the recent average candle</b>, the trade goes the <b>opposite way</b> at the next open.</li><li>You can decide to force the trade at your news time even when the candle is small. Otherwise the size of the candle decides.</li></ol>`},
  {t:'Stop, target and hold',h:tblx(['Item','Rule'],[['Stop','1 × the news candle\'s range'],['Take profit','2 × the stop'],['Hold','Open for 120 minutes, which carries the trade through the 9:30 open. Leave it alone through the open: shorter holds do not work.']])},
  {t:'Why the 9:30 open matters',h:warn('<p>The 9:30 open is the most violent part of this trade. Stops can slip past your price at the open, so size it so that a stop slipping a little further is acceptable.</p>','Slippage')},
  {t:'The FOMC evening trade',h:`<p>It is an <b>FOMC day</b> when the <b>2:00 PM candle is a big spike</b>. There are no dates to remember, and you can also decide it is an FOMC day yourself. In the evening you either <b>buy the 6:30 PM open</b> (the default) or trade the <b>break of the 6:00 to 6:30 PM opening range</b>, either way.</p>`},
  {t:'When it closes',h:`<p>Stop and target are set from the <b>typical day\'s range</b>. The trade closes at <b>3 AM</b> if neither was hit.</p>`}],
 recall:rc('INVERTIX: H/L and PO3','What are the H/L take profit and break-even rules?',['Take profit 2 × the stop, break-even at 1 × the stop','Take profit 5 × the stop, no break-even','No take profit','Take profit 1 × the stop'],'One take profit and one break-even move.'),
 steps:[['<b>The news fade.</b>',tblx(['Item','Rule'],[['Signal','News candle at least 6 × the recent average'],['Direction','Opposite way, at the next open'],['Stop','1 × the news candle\'s range'],['Take profit','2 × the stop'],['Hold','120 minutes']])],['<b>The FOMC evening.</b>',tblx(['Item','Rule'],[['Recognise','The 2:00 PM candle is a big spike'],['Trade','Buy the 6:30 PM open, or trade the break of the 6:00 to 6:30 PM range'],['Size','Stop and target from the typical day\'s range'],['Exit','Closes at 3 AM']])]],
 gens:[newsQ,fomcQ,newsRisk,sectionQ],
 bank:BANKS('News fade and FOMC evening',[
  ['When does the news fade take a trade?',['When the one-minute news candle is a big spike (at least 6 × the recent average candle)','On every release','Only when the candle is small','Never'],'The size of the candle decides, unless you force it.'],
  ['Which way does the news fade trade?',['The opposite way to the spike, at the next open','The same way as the spike','At the open only','Sideways'],'You fade the spike.'],
  ['What is the news fade stop?',['1 × the news candle\'s range','10 points','The 9:30 open','None'],'The size of the candle.'],
  ['What is the news fade take profit?',['2 × the stop','1 × the stop','40 points','None'],'2 × the stop.'],
  ['How long does the news fade stay open?',['120 minutes, which carries it through the 9:30 open','5 minutes','Until the close','30 minutes'],'Shorter holds do not work.'],
  ['Why is the 9:30 open the risky part?',['It is the most violent part and stops can slip','Nothing happens','The market is closed','It is always a win'],'Size for a stop slipping further.'],
  ['How do you recognise an FOMC day?',['The 2:00 PM candle is a big spike','The 8:30 AM candle is small','It is a Friday','You cannot'],'No dates needed.'],
  ['What is the default FOMC evening trade?',['Buy the 6:30 PM open (or trade the break of the 6:00 to 6:30 PM range)','Sell the 9:30 AM open','Trade the 2:00 PM spike','Hold with no stop'],'Two options.'],
  ['When does the FOMC evening trade close?',['At 3 AM','At 4 PM','After 5 minutes','Never'],'If neither the stop nor the target was hit.']]),
 examDesc:'The news fade rules and the FOMC evening trade.'});
/* ---------- m47 · the daily playbook ---------- */
quick({id:'m47',o:15.65,ph:7,t:'INVERTIX: The Daily Playbook',out:'Run an INVERTIX day: the routine, the stages of a setup, the ticket and what to do in each situation.',
 ls:['Before the day','Staying ready','During the day: the stages','The ticket','Managing the trade','What to do and not do','After the day'],
 task:'Set up your INVERTIX day: chart on MNQ1! at 1 minute, mark your key levels, choose your contract and your risk in dollars, and set price alerts at the levels you are watching (clock icon). Write your own loss limits on a card next to your screen.',
 learn:[
  {t:'Before the day',h:`<ul><li>Check the <b>news calendar</b> and your prop firm\'s rules. On a news morning, decide whether you will fade the news candle.</li><li>Choose your <b>risk in dollars and contract</b> (MNQ or NQ) and work out the contracts for a 30 to 90 point stop.</li><li>Choose your <b>own limits</b> and write them down (for example "stop after 2 losses, stop at −$600").</li><li>Optional: write a <b>bias for the day</b>: neutral, longs only or shorts only. It is only your opinion.</li></ul>`},
  {t:'Staying ready',h:`<p>You do not have to stare at the chart. Mark your key levels, then use the <b>alert</b> tool (the clock icon) to set <b>price alerts</b> at the levels you are watching. When one fires, open the chart and look for the flip. Use a few alerts, not dozens.</p>`},
  {t:'During the day: the stages',h:tblx(['You see','What it means','What you do'],[['Price trades into a key level','The setup starts','Mark the level and the leg'],['Watching long / short','A key level was touched; waiting for the flip','Get ready. Note the level, the leg and the window'],['A strong close through the highest small gap','The flip: every rule passes','Run the ticket, then enter at the next open'],['In the trade','You are filled','Manage with your stop guide'],['Too late','Price already ran half a stop past the entry','Skip it'],['Skipped','A rule failed (for example the stop is under 30)','Nothing: skipping is part of the plan'],['A second flip while a trade is open','Another setup','Your call: manage one trade at a time']])},
  {t:'The ticket',h:`<p>When the flip closes, run the five-point ticket (30 seconds):</p><ol><li>Is it inside a window I trade?</li><li>Is the stop between 30 and 90 points?</li><li>Is it still fine to join (price not half a stop or more past the entry)?</li><li>Is it PRIME, if I only take PRIME signals?</li><li>Am I inside my own loss limits?</li></ol>${key('<p>Any "no" means skip. Enter on a candle in your direction: a bearish candle for a short, a bullish candle for a long. If price has already run far from the entry on your chart, skip it.</p>','The rule')}`},
  {t:'Managing the trade',h:`<ul><li>Enter at the next open. Put the stop beyond the leg extreme.</li><li>When price is half a stop in profit, move your stop to your entry. <b>Once.</b> Then leave the rest alone.</li><li>The trade ends at the target, the stop, or 180 minutes after the entry. <b>Never remove the stop.</b></li><li>Do not trade the first five minutes after the 9:30 AM or 6 PM opens unless you accept the extra noise.</li></ul>`},
  {t:'What to do and not do',h:tblx(['Situation','Do','Do not'],[['The flip closes and every rule passes','Check the ticket, enter at the next open','Wait for a retest: there is none'],['Price is already half a stop past the entry','Skip it','Chase it'],['A rule fails','Skip it and note why','Take it anyway'],['A second flip while a trade is open','Your call; manage one trade at a time','Double up without a plan'],['Price is half a stop in profit','Move your stop to your entry, once','Move it sooner, or move it again'],['You hit your own loss limit','Stop for the day','Remove the limit because the signals look good'],['High-impact news in the window','Skip or stand aside around it','Assume candles behave'],['A weekend or holiday is coming','Close before the last candle before the gap','Hold through it'],['Prop evaluation','Keep risk small and use your own loss limits','Size up to pass in 3 days'],['No signal all day','Normal','Force a trade']])},
  {t:'After the day',h:`<p>Log every trade: date, window, section, key level, the stop in points, whether it was PRIME, the result in points, and whether you followed the ticket. Review the log on a schedule, not trade by trade.</p>`}],
 recall:rc('INVERTIX: News Fade and FOMC Evening','How long does the news fade stay open?',['120 minutes, which carries it through the 9:30 open','5 minutes','Until the close','30 minutes'],'Leave it alone through the open.'),
 steps:[['<b>The ticket, in short.</b>',tblx(['#','Check'],[['1','Inside a window I trade'],['2','Stop between 30 and 90 points'],['3','Not too late to join (under half a stop past the entry)'],['4','PRIME, if I only take PRIME'],['5','Inside my own loss limits']])]],
 gens:[stages,ticket,tooLate,invOrder,ownLimits],
 bank:BANKS('The daily playbook',[
  ['What do you do before the day starts?',['Check the news and your firm\'s rules, set your size and write your limits','Place a trade at the open','Turn off the stop','Switch to the daily chart'],'News, rules, size, limits.'],
  ['How do you stay ready without staring at the chart?',['Set price alerts at the key levels you are watching','Check every candle all day','Turn off all alerts','Trade a different market'],'Mark the levels, set price alerts, then look for the flip when one fires.'],
  ['Price is already half a stop or more past the entry. What do you do?',['Skip it','Chase it with a wider stop','Add contracts','Remove the stop'],'It is too late to join.'],
  ['The flip closes and every rule passes. What is the first thing you do?',['Run the ticket','Enter at once','Wait for a retest','Close your other trade'],'The ticket takes 30 seconds.'],
  ['The stop on a signal would be 24 points. What do you do?',['Skip it: under 30 points','Take it with a wider stop','Take it at half size','Wait for a retest'],'The ticket needs a stop of 30 to 90 points.'],
  ['On which candle do you enter?',['One in your direction: bearish for a short, bullish for a long','Any candle','The biggest candle','The last candle of the window'],'Enter on a candle in your direction.'],
  ['A second flip forms while a trade is open. What do you do?',['Your call: manage one trade at a time','Cancel the first trade','Double the size','Remove the stop'],'One trade at a time.'],
  ['Price is half a stop in profit. What do you do?',['Move your stop to your entry, once','Close the trade','Move the target','Remove the stop'],'The trade stays open.'],
  ['You hit your own loss limit. What do you do?',['Stop for the day','Remove the limit','Take one more','Double the size'],'The limit is yours: keep it.'],
  ['Why be careful in the first five minutes after 9:30 or 6 PM?',['Opens are noisy and stops can slip','Nothing happens then','The market is closed','Trades always win'],'Accept the extra noise or wait.'],
  ['Nothing prints all day. What do you do?',['Nothing: that is a normal day','Force a trade','Loosen every rule','Switch to the 5-minute chart'],'No signal is normal.']]),
 examDesc:'The routine, the stages of a setup, the five-point ticket and what to do in each situation.'});
})();
